export type RegisteredGlyphStyle = keyof typeof glyphRegistry;
export type RegisteredGlyphName = (typeof glyphRegistry)[RegisteredGlyphStyle][number];

const glyphNames = {
  line: new Set<string>(glyphRegistry.line),
  fill: new Set<string>(glyphRegistry.fill),
} satisfies Record<RegisteredGlyphStyle, ReadonlySet<string>>;

export function hasGlyph(style: RegisteredGlyphStyle, name: string): boolean {
  return glyphNames[style].has(name);
}
